"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { CheckCircle2, XCircle } from "lucide-react";

const ROLES = ['SUPER_ADMIN', 'INSTITUTION_ADMIN', 'RESEARCHER', 'AUDITOR'];

function getInitials(name: string) {
  return name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
}

export default function AdminPage() {
  const [users, setUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchUsers = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/admin/users`, { headers: { Authorization: `Bearer ${session.access_token}` } });
    if (res.ok) setUsers(await res.json());
    setLoading(false);
  };

  useEffect(() => { fetchUsers(); }, []);

  const handleRoleChange = async (userId: string, newRole: string) => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/admin/users/${userId}/role`, {
      method: "PATCH", headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` }, body: JSON.stringify({ role: newRole }),
    });
    if (res.ok) { setUsers(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u)); toast.success("Role updated"); }
  };

  const handleApprove = async (userId: string) => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/admin/users/${userId}/approve`, {
      method: "PATCH", headers: { Authorization: `Bearer ${session.access_token}` },
    });
    if (res.ok) { setUsers(prev => prev.map(u => u.id === userId ? { ...u, isApproved: true } : u)); toast.success("User approved"); }
  };

  if (loading) return <div className="p-8 text-muted-foreground animate-pulse">Loading users...</div>;

  return (
    <div className="space-y-6">
      <h1 className="text-3xl font-display font-bold">Admin Panel</h1>
      <div className="border border-border rounded-lg bg-card overflow-hidden">
        <table className="w-full text-sm text-left">
          <thead className="bg-secondary/50 text-xs uppercase text-muted-foreground">
            <tr>
              <th className="px-4 py-3">User</th>
              <th className="px-4 py-3">Role</th>
              <th className="px-4 py-3">Status</th>
            </tr>
          </thead>
          <tbody>
            {users.map((u) => (
              <tr key={u.id} className="border-b border-border">
                <td className="px-4 py-3">
                  <div className="flex items-center gap-3">
                    <div className="h-8 w-8 rounded-full bg-primary/10 text-primary flex items-center justify-center font-bold text-xs">{getInitials(u.fullName)}</div>
                    <div><p className="font-medium text-foreground">{u.fullName}</p><p className="text-xs text-muted-foreground">{u.email}</p></div>
                  </div>
                </td>
                <td className="px-4 py-3">
                  <select value={u.role} onChange={(e) => handleRoleChange(u.id, e.target.value)} className="px-2 py-1 border border-border rounded-md bg-background text-xs">
                    {ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
                  </select>
                </td>
                <td className="px-4 py-3">
                  {u.isApproved ? (
                    <span className="inline-flex items-center gap-1 text-xs font-medium text-green-500"><CheckCircle2 className="h-3 w-3" /> Approved</span>
                  ) : (
                    <div className="flex items-center gap-3">
                      <span className="inline-flex items-center gap-1 text-xs font-medium text-orange-500"><XCircle className="h-3 w-3" /> Pending</span>
                      <Button size="sm" onClick={() => handleApprove(u.id)}>Approve</Button>
                    </div>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";
import { useState } from "react";
import { supabase } from "@/lib/supabase";
import { ShieldAlert, Play, CheckCircle2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

export default function AnonymisePage() {
  const [datasetId, setDatasetId] = useState("");
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  const handleAnonymise = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;

    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/enterprise/anonymise`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
      body: JSON.stringify({ datasetId }),
    });

    if (res.ok) { setSuccess(true); toast.success("Anonymisation job started"); }
    else { toast.error("Failed to start job"); }
    setLoading(false);
  };

  return (
    <div className="space-y-6 max-w-2xl">
      <div>
        <h1 className="text-3xl font-display font-bold">Data Anonymisation</h1>
        <p className="text-muted-foreground mt-1">Generate privacy-protected copies of research datasets.</p>
      </div>

      <div className="p-6 border border-border rounded-lg bg-card">
        <form onSubmit={handleAnonymise} className="space-y-4">
          <div>
            <label className="text-sm font-medium">Dataset ID or Name</label>
            <input required value={datasetId} onChange={(e) => setDatasetId(e.target.value)} className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background text-sm" placeholder="e.g. 123e4567-e89b-12d3-a456-426614174000" />
          </div>
          <Button type="submit" disabled={loading} className="w-full">
            {loading ? "Processing..." : <><ShieldAlert className="mr-2 h-4 w-4" /> Start Anonymisation</>}
          </Button>
        </form>
      </div>

      {success && (
        <div className="p-6 border border-green-500/30 bg-green-500/10 rounded-lg flex items-start gap-4">
          <CheckCircle2 className="h-6 w-6 text-green-500 mt-1" />
          <div>
            <h3 className="font-semibold text-green-500">Job Queued Successfully</h3>
            <p className="text-sm text-muted-foreground mt-1">The dataset is being processed. An authorised reviewer must approve the release before it becomes available in the catalogue.</p>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Button } from "@/components/ui/button";

export default function AuditPage() {
  const [logs, setLogs] = useState<any[]>([]);
  const [actionFilter, setActionFilter] = useState("");
  const [loading, setLoading] = useState(true);

  const fetchLogs = async () => {
    setLoading(true);
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;

    const url = new URL(`${process.env.NEXT_PUBLIC_API_URL}/audit`, window.location.origin);
    if (actionFilter) url.searchParams.append("action", actionFilter);

    const res = await fetch(url.toString(), {
      headers: { Authorization: `Bearer ${session.access_token}` },
    });

    if (res.ok) setLogs(await res.json());
    setLoading(false);
  };

  useEffect(() => {
    fetchLogs();
  }, [actionFilter]);

  const handleExportCSV = () => {
    if (logs.length === 0) return;

    const headers = ["ID", "Action", "Time", "Actor ID", "Row Hash", "Prev Hash"];
    const rows = logs.map((l) => [
      l.id,
      l.action,
      new Date(l.createdAt).toISOString(),
      l.actorId,
      l.rowHash,
      l.prevHash || "GENESIS",
    ]);

    const csvContent = [
      headers.join(","),
      ...rows.map((r) => r.map((cell) => `"${cell}"`).join(",")),
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `audit-log-${Date.now()}.csv`);
    link.click();
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-3xl font-display font-bold">Security Audit Trail</h1>
          <p className="text-muted-foreground mt-1">Immutable cryptographic ledger of all institutional activity.</p>
        </div>
        <Button onClick={handleExportCSV} disabled={logs.length === 0}>
          Export to CSV
        </Button>
      </div>

      <div className="flex gap-4 p-4 border border-border rounded-lg bg-card">
        <div className="flex-1">
          <label className="text-xs font-medium text-muted-foreground mb-1 block">Filter by Action</label>
          <select
            value={actionFilter}
            onChange={(e) => setActionFilter(e.target.value)}
            className="w-full px-3 py-2 border border-border rounded-md bg-background text-sm"
          >
            <option value="">All Actions</option>
            <option value="UPLOAD_RESOURCE">UPLOAD_RESOURCE</option>
            <option value="DELETE_RESOURCE">DELETE_RESOURCE</option>
            <option value="CHANGE_USER_ROLE">CHANGE_USER_ROLE</option>
          </select>
        </div>
      </div>

      <div className="border border-border rounded-lg bg-card overflow-hidden">
        {loading ? (
          <div className="p-8 text-center text-muted-foreground">Loading audit logs...</div>
        ) : logs.length === 0 ? (
          <div className="p-8 text-center text-muted-foreground">No logs found for the selected filter.</div>
        ) : (
          <table className="w-full text-sm text-left">
            <thead className="bg-secondary/50 text-xs uppercase text-muted-foreground">
              <tr>
                <th className="px-4 py-3">Action</th>
                <th className="px-4 py-3">Time</th>
                <th className="px-4 py-3 font-mono">Row Hash</th>
                <th className="px-4 py-3 font-mono">Prev Hash</th>
              </tr>
            </thead>
            <tbody>
              {logs.map((log) => (
                <tr key={log.id} className="border-b border-border">
                  <td className="px-4 py-3 text-primary font-medium">{log.action}</td>
                  <td className="px-4 py-3 text-muted-foreground">
                    {new Date(log.createdAt).toLocaleString()}
                  </td>
                  <td className="px-4 py-3 font-mono text-green-600 text-xs" title={log.rowHash}>
                    {log.rowHash.slice(0, 16)}...
                  </td>
                  <td className="px-4 py-3 font-mono text-blue-600 text-xs" title={log.prevHash || 'GENESIS'}>
                    {log.prevHash ? log.prevHash.slice(0, 16) + '...' : 'GENESIS'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Database, Search, FileText, Lock, ShieldAlert, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

export default function CataloguePage() {
  const [datasets, setDatasets] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [role, setRole] = useState("");
  const [isCreating, setIsCreating] = useState(false);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [classification, setClassification] = useState("PUBLIC");

  const loadPageData = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const h = { Authorization: `Bearer ${session.access_token}` };
    const [catRes, meRes] = await Promise.all([
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/enterprise/catalogue?search=${search}`, { headers: h }),
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/users/me`, { headers: h })
    ]);
    if (meRes.ok) setRole((await meRes.json()).role);
    if (catRes.ok) setDatasets(await catRes.json());
  };

  useEffect(() => { const t = setTimeout(() => loadPageData(), 300); return () => clearTimeout(t); }, [search]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/enterprise/catalogue`, {
      method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
      body: JSON.stringify({ name, description, classification }),
    });
    if (res.ok) { toast.success("Dataset created"); setIsCreating(false); setName(""); setDescription(""); loadPageData(); }
    else { toast.error("Failed to create dataset"); }
  };

  const isAdmin = role === 'INSTITUTION_ADMIN' || role === 'SUPER_ADMIN';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-3xl font-display font-bold">Research Data Catalogue</h1>
          <p className="text-muted-foreground mt-1">Discover and request access to institutional datasets.</p>
        </div>
        {isAdmin && <Button onClick={() => setIsCreating(!isCreating)}><Plus className="mr-2 h-4 w-4" /> Add Dataset</Button>}
      </div>

      {isCreating && (
        <form onSubmit={handleCreate} className="p-4 border border-border rounded-lg bg-card space-y-4 max-w-xl">
          <div><label className="text-sm font-medium">Dataset Name</label><input required value={name} onChange={e => setName(e.target.value)} className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background text-sm" /></div>
          <div><label className="text-sm font-medium">Description</label><textarea value={description} onChange={e => setDescription(e.target.value)} className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background text-sm resize-none" rows={2} /></div>
          <div><label className="text-sm font-medium">Classification</label><select value={classification} onChange={e => setClassification(e.target.value)} className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background text-sm"><option value="PUBLIC">Public</option><option value="RESTRICTED">Restricted</option></select></div>
          <div className="flex gap-2"><Button type="submit">Save Dataset</Button><Button type="button" variant="ghost" onClick={() => setIsCreating(false)}>Cancel</Button></div>
        </form>
      )}

      <div className="relative w-full max-w-md">
        <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
        <input type="text" placeholder="Search datasets..." value={search} onChange={(e) => setSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 border border-border rounded-md bg-background text-sm focus:outline-none focus:ring-1 focus:ring-primary" />
      </div>

      {datasets.length === 0 ? (
        <div className="text-center py-20 border border-border rounded-lg border-dashed bg-card"><Database className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" /><h3 className="text-lg font-semibold">No datasets found</h3></div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {datasets.map((d) => (
            <div key={d.id} className="p-6 border border-border rounded-lg bg-card flex flex-col justify-between">
              <div>
                <div className="flex justify-between items-start mb-4">
                  <Database className="h-8 w-8 text-primary" />
                  <span className={`inline-flex items-center gap-1 text-[10px] font-bold uppercase px-2 py-1 rounded ${d.classification === 'RESTRICTED' ? 'text-red-500 bg-red-500/10' : 'text-green-500 bg-green-500/10'}`}>{d.classification === 'RESTRICTED' ? <ShieldAlert className="h-3 w-3" /> : null} {d.classification}</span>
                </div>
                <h3 className="font-semibold text-lg">{d.name}</h3>
                <p className="text-sm text-muted-foreground mt-1">{d.description || "No description"}</p>
                <div className="mt-4 flex items-center gap-4 text-xs text-muted-foreground"><span className="flex items-center gap-1"><FileText className="h-3 w-3" /> Dataset</span><span className="flex items-center gap-1"><Lock className="h-3 w-3" /> {d.classification}</span></div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import { Building, Trash2, Pencil, Check, X } from "lucide-react";
import { toast } from "sonner";

export default function DepartmentsPage() {
  const [departments, setDepartments] = useState<any[]>([]);
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(true);
  const [role, setRole] = useState("");

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState("");

  const fetchDeps = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const h = { Authorization: `Bearer ${session.access_token}` };

    const [res, meRes] = await Promise.all([
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/departments`, { headers: h }),
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/users/me`, { headers: h })
    ]);

    if (meRes.ok) { const me = await meRes.json(); setRole(me.role); }
    if (res.ok) setDepartments(await res.json());
    setLoading(false);
  };

  useEffect(() => { fetchDeps(); }, []);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;

    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/departments`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
      body: JSON.stringify({ name })
    });

    if (res.ok) { toast.success("Department added"); setName(""); fetchDeps(); }
    else { toast.error("Failed to add department"); }
  };

  const handleSaveEdit = async (id: string) => {
    if (!editName.trim()) return toast.error("Name cannot be empty");
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;

    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/departments/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
      body: JSON.stringify({ name: editName })
    });

    if (res.ok) { toast.success("Department updated"); setEditingId(null); fetchDeps(); }
    else { toast.error("Failed to update"); }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure? Projects inside this department will also be deleted.")) return;
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;

    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/departments/${id}`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${session.access_token}` }
    });

    if (res.ok) { toast.success("Department deleted"); fetchDeps(); }
    else { toast.error("Failed to delete."); }
  };

  if (loading) return <div className="p-8 text-muted-foreground animate-pulse">Loading departments...</div>;

  const isAdmin = role === "INSTITUTION_ADMIN" || role === "SUPER_ADMIN";

  return (
    <div className="space-y-6 max-w-2xl">
      <h1 className="text-3xl font-display font-bold">Departments</h1>

      {isAdmin && (
        <form onSubmit={handleCreate} className="flex gap-4">
          <input value={name} onChange={(e) => setName(e.target.value)} placeholder="New department" className="flex-1 px-3 py-2 border border-border rounded-md bg-background text-sm" />
          <Button type="submit">Add Department</Button>
        </form>
      )}

      {departments.length === 0 ? (
        <div className="text-center py-16 border border-border rounded-lg border-dashed bg-card">
          <Building className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
          <h3 className="text-lg font-semibold">No departments yet</h3>
        </div>
      ) : (
        <div className="space-y-2">
          {departments.map(d => (
            <div key={d.id} className="flex items-center justify-between p-4 border border-border rounded-lg bg-card transition-colors">
              {editingId === d.id ? (
                <div className="flex-1 flex gap-2 items-center mr-4">
                  <input type="text" value={editName} onChange={(e) => setEditName(e.target.value)} className="flex-1 px-3 py-1 border border-border rounded-md bg-background text-sm" autoFocus onKeyDown={(e) => { if (e.key === 'Enter') handleSaveEdit(d.id); if (e.key === 'Escape') setEditingId(null); }} />
                  <Button type="button" size="sm" onClick={() => handleSaveEdit(d.id)}><Check className="h-4 w-4" /></Button>
                  <Button type="button" variant="ghost" size="sm" onClick={() => setEditingId(null)}><X className="h-4 w-4" /></Button>
                </div>
              ) : (
                <span className="font-medium">{d.name}</span>
              )}

              {isAdmin && editingId !== d.id && (
                <div className="flex gap-2">
                  <button onClick={() => { setEditingId(d.id); setEditName(d.name); }} className="p-2 text-muted-foreground hover:text-primary rounded-md hover:bg-primary/10 transition-colors">
                    <Pencil className="h-4 w-4" />
                  </button>
                  <button onClick={() => handleDelete(d.id)} className="p-2 text-muted-foreground hover:text-red-500 rounded-md hover:bg-red-500/10 transition-colors">
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { DollarSign, Calendar, Building, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

export default function GrantsPage() {
  const [grants, setGrants] = useState<any[]>([]);
  const [role, setRole] = useState("");
  const [isCreating, setIsCreating] = useState(false);
  const [name, setName] = useState("");
  const [funder, setFunder] = useState("");
  const [amount, setAmount] = useState("");
  const [endDate, setEndDate] = useState("");

  const loadPageData = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const h = { Authorization: `Bearer ${session.access_token}` };
    const [grantRes, meRes] = await Promise.all([
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/enterprise/grants`, { headers: h }),
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/users/me`, { headers: h })
    ]);
    if (meRes.ok) setRole((await meRes.json()).role);
    if (grantRes.ok) setGrants(await grantRes.json());
  };

  useEffect(() => { loadPageData(); }, []);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/enterprise/grants`, {
      method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
      body: JSON.stringify({ name, funder, amount: Number(amount), endDate: new Date(endDate) }),
    });
    if (res.ok) { toast.success("Grant created"); setIsCreating(false); setName(""); setFunder(""); setAmount(""); setEndDate(""); loadPageData(); }
    else { toast.error("Failed to create grant"); }
  };

  const isAdmin = role === 'INSTITUTION_ADMIN' || role === 'SUPER_ADMIN';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-3xl font-display font-bold">Research Grants & Funding</h1>
          <p className="text-muted-foreground mt-1">Track institutional funding, budgets, and deadlines.</p>
        </div>
        {isAdmin && <Button onClick={() => setIsCreating(!isCreating)}><Plus className="mr-2 h-4 w-4" /> Add Grant</Button>}
      </div>

      {isCreating && (
        <form onSubmit={handleCreate} className="p-4 border border-border rounded-lg bg-card grid grid-cols-2 gap-4 max-w-2xl">
          <div className="col-span-2"><label className="text-sm font-medium">Grant Name</label><input required value={name} onChange={e => setName(e.target.value)} className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background text-sm" /></div>
          <div><label className="text-sm font-medium">Funder</label><input required value={funder} onChange={e => setFunder(e.target.value)} className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background text-sm" /></div>
          <div><label className="text-sm font-medium">Amount (USD)</label><input type="number" required value={amount} onChange={e => setAmount(e.target.value)} className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background text-sm" /></div>
          <div className="col-span-2"><label className="text-sm font-medium">End Date</label><input type="date" required value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background text-sm" /></div>
          <div className="col-span-2 flex gap-2"><Button type="submit">Save Grant</Button><Button type="button" variant="ghost" onClick={() => setIsCreating(false)}>Cancel</Button></div>
        </form>
      )}

      {grants.length === 0 ? (
        <div className="text-center py-20 border border-border rounded-lg border-dashed bg-card"><DollarSign className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" /><h3 className="text-lg font-semibold">No active grants</h3></div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {grants.map((g) => (
            <div key={g.id} className="p-6 border border-border rounded-lg bg-card">
              <div className="flex justify-between items-start mb-4"><DollarSign className="h-8 w-8 text-green-500" /><span className="text-2xl font-bold text-green-500">{g.currency} {g.amount.toLocaleString()}</span></div>
              <h3 className="font-semibold text-lg">{g.name}</h3>
              <p className="text-sm text-muted-foreground flex items-center gap-1 mt-1"><Building className="h-3 w-3" /> {g.funder}</p>
              <p className="text-sm text-muted-foreground flex items-center gap-1 mt-1"><Calendar className="h-3 w-3" /> Ends: {new Date(g.endDate).toLocaleDateString()}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { useRouter, usePathname } from "next/navigation";
import { supabase } from "@/lib/supabase";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { ShieldCheck, Folder, Building, Users, ScrollText, LogOut, LayoutDashboard, Trash2, Database, ShieldAlert, DollarSign } from "lucide-react";
import { toast } from "sonner";

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const pathname = usePathname();
  const [user, setUser] = useState<any>(null);
  const [role, setRole] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  useEffect(() => {
    const init = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) { router.push("/login"); return; }

      try {
        const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/users/me`, { headers: { Authorization: `Bearer ${session.access_token}` } });

        if (!res.ok) {
          if (res.status === 401) {
            setErrorMsg("Your account is pending admin approval, or you have been logged out.");
            await supabase.auth.signOut();
          } else {
            const err = await res.json().catch(() => ({}));
            setErrorMsg(`Server Error (${res.status}): ${err.message || "Check backend terminal"}`);
          }
          return;
        }

        const data = await res.json();
        setUser(session.user);
        setRole(data.role);
      } catch (e: any) {
        setErrorMsg(`Network Error: ${e.message}. Is the backend running?`);
      }
    };
    init();
  }, [router]);

  const handleSignOut = async () => {
    if (!confirm("Are you sure you want to sign out?")) return;
    await supabase.auth.signOut();
    toast.success("Signed out");
    router.push("/");
  };

  if (errorMsg) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4">
        <div className="max-w-md w-full border border-red-500/50 bg-red-500/10 p-6 rounded-lg text-center space-y-4">
          <ShieldAlert className="h-10 w-10 text-red-500 mx-auto" />
          <h2 className="text-xl font-bold text-red-500">Access Denied</h2>
          <p className="text-sm text-foreground">{errorMsg}</p>
          <Button onClick={() => { setErrorMsg(null); router.push("/login"); }}>Go to Login</Button>
        </div>
      </div>
    );
  }

  if (!user) return <div className="min-h-screen flex items-center justify-center animate-pulse">Checking permissions...</div>;

  const isAdmin = role === 'INSTITUTION_ADMIN' || role === 'SUPER_ADMIN';
  const isAuditor = role === 'AUDITOR';

  const navItems = [
    { name: "Overview", href: "/dashboard", icon: LayoutDashboard, show: true },
    { name: "Catalogue", href: "/dashboard/catalogue", icon: Database, show: true },
    { name: "Projects", href: "/dashboard/projects", icon: Folder, show: !isAuditor },
    { name: "Departments", href: "/dashboard/departments", icon: Building, show: !isAuditor },
    { name: "Grants", href: "/dashboard/grants", icon: DollarSign, show: isAdmin || role === 'RESEARCHER' },
    { name: "Anonymisation", href: "/dashboard/anonymise", icon: ShieldAlert, show: isAdmin || role === 'RESEARCHER' },
    { name: "Trash", href: "/dashboard/trash", icon: Trash2, show: !isAuditor },
    { name: "Audit Trail", href: "/dashboard/audit", icon: ScrollText, show: isAdmin || isAuditor },
    { name: "Admin Panel", href: "/dashboard/admin", icon: Users, show: isAdmin }, 
  ].filter(item => item.show);

  return (
    <div className="flex h-screen bg-background">
      <aside className="w-64 border-r border-border bg-card flex flex-col hidden md:flex">
        <Link href="/dashboard" className="p-6 flex items-center gap-2 border-b border-border hover:bg-secondary/40 transition-colors">
          <ShieldCheck className="h-6 w-6 text-primary" />
          <span className="font-display font-bold text-lg">Research Vault</span>
        </Link>
        <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
          {navItems.map((item) => {
            const isActive = pathname === item.href;
            const Icon = item.icon;
            return (
              <Link key={item.name} href={item.href} 
                className={`flex items-center gap-3 px-3 py-2 rounded-md text-sm font-medium transition-colors ${isActive ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-secondary'}`}
              >
                <Icon className="h-4 w-4" />{item.name}
              </Link>
            );
          })}
        </nav>
        <div className="p-4 border-t border-border">
          <div className="inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold bg-primary/10 text-primary mb-2">{role}</div>
          <p className="text-xs text-muted-foreground mb-3 truncate">{user.email}</p>
          <Button variant="danger" className="w-full justify-start gap-2" onClick={handleSignOut}>
            <LogOut className="h-4 w-4" /> Sign Out
          </Button>
        </div>
      </aside>
      <main className="flex-1 overflow-y-auto"><div className="p-8 max-w-6xl mx-auto">{children}</div></main>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Folder, Building, FileText, HardDrive, ArrowRight, Activity, Clock } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";

export default function OverviewPage() {
  const [user, setUser] = useState<any>(null);
  const [stats, setStats] = useState({ projects: 0, departments: 0, files: 0, size: 0 });
  const [recentActivity, setRecentActivity] = useState<any[]>([]);

  useEffect(() => {
    const fetchDashboardData = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) return;
      setUser(session.user);
      const h = { Authorization: `Bearer ${session.access_token}` };

      const [projRes, depRes, resRes, auditRes] = await Promise.all([
        fetch(`${process.env.NEXT_PUBLIC_API_URL}/projects`, { headers: h }),
        fetch(`${process.env.NEXT_PUBLIC_API_URL}/departments`, { headers: h }),
        fetch(`${process.env.NEXT_PUBLIC_API_URL}/resources`, { headers: h }),
        fetch(`${process.env.NEXT_PUBLIC_API_URL}/audit`, { headers: h })
      ]);

      let pCount = 0, dCount = 0, fCount = 0, totalSize = 0;
      let recent: any[] = [];

      if (projRes.ok) { const p = await projRes.json(); pCount = p.length; }
      if (depRes.ok) { const d = await depRes.json(); dCount = d.length; }
      if (resRes.ok) { 
        const r = await resRes.json(); 
        fCount = r.length; 
        totalSize = r.reduce((acc: number, curr: any) => acc + Number(curr.sizeBytes || 0), 0);
      }
      if (auditRes.ok) { const a = await auditRes.json(); recent = a.slice(0, 5); }

      setStats({ projects: pCount, departments: dCount, files: fCount, size: totalSize });
      setRecentActivity(recent);
    };
    fetchDashboardData();
  }, []);

  const formatSize = (bytes: number) => {
    if (bytes === 0) return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
  };

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-display font-bold">My Workspace</h1>
        <p className="text-muted-foreground mt-1">Welcome back, {user?.user_metadata?.full_name || user?.email || "Loading..."}.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="p-6 border border-border rounded-lg bg-card">
          <div className="p-2 bg-primary/10 rounded-md w-fit mb-4"><Folder className="h-5 w-5 text-primary" /></div>
          <p className="text-sm font-medium text-muted-foreground">Total Projects</p>
          <h3 className="text-3xl font-bold">{stats.projects}</h3>
        </div>
        <div className="p-6 border border-border rounded-lg bg-card">
          <div className="p-2 bg-blue-500/10 rounded-md w-fit mb-4"><Building className="h-5 w-5 text-blue-500" /></div>
          <p className="text-sm font-medium text-muted-foreground">Departments</p>
          <h3 className="text-3xl font-bold">{stats.departments}</h3>
        </div>
        <div className="p-6 border border-border rounded-lg bg-card">
          <div className="p-2 bg-green-500/10 rounded-md w-fit mb-4"><FileText className="h-5 w-5 text-green-500" /></div>
          <p className="text-sm font-medium text-muted-foreground">Files Uploaded</p>
          <h3 className="text-3xl font-bold">{stats.files}</h3>
        </div>
        <div className="p-6 border border-border rounded-lg bg-card">
          <div className="p-2 bg-purple-500/10 rounded-md w-fit mb-4"><HardDrive className="h-5 w-5 text-purple-500" /></div>
          <p className="text-sm font-medium text-muted-foreground">Storage Used</p>
          <h3 className="text-3xl font-bold">{formatSize(stats.size)}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 border border-border rounded-lg bg-card p-6">
          <h3 className="font-semibold text-lg mb-4 flex items-center gap-2"><ArrowRight className="h-5 w-5 text-primary" /> Quick Actions</h3>
          <div className="space-y-3">
            <Link href="/dashboard/projects" className="block"><Button variant="outline" className="w-full justify-start h-12"><Folder className="mr-2 h-4 w-4 text-primary" /> Go to Projects</Button></Link>
            <Link href="/dashboard/departments" className="block"><Button variant="outline" className="w-full justify-start h-12"><Building className="mr-2 h-4 w-4 text-blue-500" /> Manage Departments</Button></Link>
            <Link href="/dashboard/trash" className="block"><Button variant="outline" className="w-full justify-start h-12"><HardDrive className="mr-2 h-4 w-4 text-muted-foreground" /> View Trash Bin</Button></Link>
          </div>
        </div>
        <div className="lg:col-span-2 border border-border rounded-lg bg-card p-6">
          <h3 className="font-semibold text-lg mb-4 flex items-center gap-2"><Activity className="h-5 w-5 text-green-500" /> Recent Activity</h3>
          {recentActivity.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground"><Clock className="h-8 w-8 mx-auto mb-2 opacity-50" /><p>No recent activity.</p></div>
          ) : (
            <div className="space-y-4">
              {recentActivity.map((act: any) => (
                <div key={act.id} className="flex items-start gap-3 pb-3 border-b border-border last:border-0 last:pb-0">
                  <div className="h-8 w-8 rounded-full bg-secondary flex items-center justify-center shrink-0"><Activity className="h-4 w-4 text-muted-foreground" /></div>
                  <div><p className="text-sm font-medium">{act.action.replace(/_/g, ' ')}</p><p className="text-xs text-muted-foreground">{new Date(act.createdAt).toLocaleString()}</p></div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState, useMemo } from "react";
import { supabase } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import { useParams } from "next/navigation";
import { FileText, ArrowUpDown, Image as ImageIcon, File, History, Filter, UploadCloud, Loader2 } from "lucide-react";
import { toast } from "sonner";

export default function ProjectDetails() {
  const params = useParams();
  const projectId = params.id as string;

  const [resources, setResources] = useState<any[]>([]);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [file, setFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  const [dragActive, setDragActive] = useState(false);

  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [previewType, setPreviewType] = useState<string | null>(null);
  const [shareResource, setShareResource] = useState<any>(null);
  const [shareUrl, setShareUrl] = useState<string | null>(null);

  const [sortConfig, setSortConfig] = useState<{ key: string, direction: "asc" | "desc" } | null>(null);
  const [filterType, setFilterType] = useState("ALL");
  const [filterUser, setFilterUser] = useState("ALL");

  // Per-row loading state
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const [versionsResource, setVersionsResource] = useState<any>(null);
  const [versionsList, setVersionsList] = useState<any[]>([]);

  const getFileIcon = (mimeType: string) => {
    if (mimeType.startsWith("image/")) return <ImageIcon className="h-4 w-4 text-purple-500" />;
    if (mimeType.includes("pdf")) return <FileText className="h-4 w-4 text-red-500" />;
    if (mimeType.includes("word")) return <FileText className="h-4 w-4 text-blue-500" />;
    if (mimeType.includes("presentation")) return <FileText className="h-4 w-4 text-orange-500" />;
    return <File className="h-4 w-4 text-gray-500" />;
  };

  const fetchResources = async (token?: string) => {
    const jwt = token || (await supabase.auth.getSession()).data.session?.access_token;
    if (!jwt) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/resources?projectId=${projectId}`, { headers: { Authorization: `Bearer ${jwt}` } });
    if (res.ok) setResources(await res.json());
  };

  useEffect(() => {
    const init = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session) setCurrentUser(session.user);
      fetchResources(session?.access_token);
    };
    init();
    const channel = supabase.channel('resource-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'resources', filter: `project_id=eq.${projectId}` }, () => { fetchResources(); }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId]);

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault(); e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") setDragActive(true);
    else if (e.type === "dragleave") setDragActive(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault(); e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) setFile(e.dataTransfer.files[0]);
  };

  const handleUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;
    setUploading(true);
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;

    const filePath = `${session.user.user_metadata.institution_id}/${Date.now()}_${file.name}`;
    await supabase.storage.from("research-vault").upload(filePath, file);

    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/resources`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
      body: JSON.stringify({ projectId, name: file.name, filePath, mimeType: file.type, sizeBytes: file.size }),
    });

    if (!res.ok) toast.error("Failed to upload file");
    else { toast.success("File uploaded"); setFile(null); }
    setUploading(false);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Delete this file?")) return;
    setDeletingId(id);
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/resources/${id}`, { method: "DELETE", headers: { Authorization: `Bearer ${session.access_token}` } });
    if (res.ok) toast.success("File deleted");
    setDeletingId(null);
  };

  const handlePreview = async (filePath: string, mimeType: string) => {
    const { data } = await supabase.storage.from("research-vault").createSignedUrl(filePath, 60);
    if (data) { setPreviewUrl(data.signedUrl); setPreviewType(mimeType); }
  };

  const handleDownload = async (filePath: string) => {
    const { data } = await supabase.storage.from("research-vault").createSignedUrl(filePath, 60);
    if (data) window.open(data.signedUrl, "_blank");
  };

  const handleCreateShare = async (resource: any, hours: number) => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/share/${resource.id}`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
      body: JSON.stringify({ expiresInHours: hours }),
    });
    if (res.ok) { const data = await res.json(); setShareUrl(data.url); toast.success("Share link generated"); }
  };

  const handleShowVersions = async (resource: any) => {
    setVersionsResource(resource);
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/resources/versions?projectId=${projectId}&name=${encodeURIComponent(resource.name)}`, { headers: { Authorization: `Bearer ${session.access_token}` } });
    if (res.ok) setVersionsList(await res.json());
  };

  const requestSort = (key: string) => {
    let direction: "asc" | "desc" = "asc";
    if (sortConfig && sortConfig.key === key && sortConfig.direction === "asc") direction = "desc";
    setSortConfig({ key, direction });
  };

  const filteredAndSortedResources = useMemo(() => {
    let items = [...resources];
    if (filterType !== "ALL") items = items.filter(r => {
      if (filterType === "IMAGE") return r.mimeType.startsWith("image/");
      if (filterType === "PDF") return r.mimeType.includes("pdf");
      if (filterType === "DOC") return r.mimeType.includes("word") || r.mimeType.includes("presentation");
      return true;
    });
    if (filterUser === "ME" && currentUser) items = items.filter(r => r.uploadedBy === currentUser.id);
    if (sortConfig !== null) items.sort((a, b) => {
      if (a[sortConfig.key] < b[sortConfig.key]) return sortConfig.direction === "asc" ? -1 : 1;
      if (a[sortConfig.key] > b[sortConfig.key]) return sortConfig.direction === "asc" ? 1 : -1;
      return 0;
    });
    return items;
  }, [resources, filterType, filterUser, sortConfig, currentUser]);

  return (
    <div className="space-y-6 max-w-6xl">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-display font-bold">Project Files</h1>
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <span className="relative flex h-3 w-3">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
          </span>
          Live Updates
        </div>
      </div>

      <form onSubmit={handleUpload}>
        <div 
          className={`border-2 border-dashed rounded-lg p-10 text-center transition-colors ${dragActive ? 'border-primary bg-primary/5' : 'border-border bg-card'}`}
          onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
        >
          <input type="file" id="fileUpload" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} />
          <label htmlFor="fileUpload" className="cursor-pointer">
            <UploadCloud className="mx-auto h-8 w-8 text-muted-foreground mb-2" />
            <p className="text-sm font-medium text-foreground">
              {file ? file.name : "Drag and drop your file here, or click to browse"}
            </p>
          </label>
        </div>
        <div className="flex justify-end mt-4">
          <Button type="submit" disabled={!file || uploading}>
            {uploading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" /> Uploading...</> : "Upload File"}
          </Button>
        </div>
      </form>

      <div className="flex flex-wrap items-center gap-4 p-4 border border-border rounded-lg bg-card">
        <div className="flex items-center gap-2 text-sm font-medium"><Filter className="h-4 w-4" /> Filters:</div>
        <select value={filterType} onChange={(e) => setFilterType(e.target.value)} className="px-3 py-1.5 border border-border rounded-md bg-background text-sm">
          <option value="ALL">All File Types</option>
          <option value="IMAGE">Images</option>
          <option value="PDF">PDFs</option>
          <option value="DOC">Documents</option>
        </select>
        <select value={filterUser} onChange={(e) => setFilterUser(e.target.value)} className="px-3 py-1.5 border border-border rounded-md bg-background text-sm">
          <option value="ALL">Uploaded by Anyone</option>
          <option value="ME">Uploaded by Me</option>
        </select>
        <div className="text-xs text-muted-foreground ml-auto">Showing {filteredAndSortedResources.length} of {resources.length}</div>
      </div>

      {filteredAndSortedResources.length === 0 ? (
        <div className="text-center py-20 border border-border rounded-lg border-dashed bg-card">
          <FileText className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
          <h3 className="text-lg font-semibold">No files match your filters</h3>
        </div>
      ) : (
        <div className="border border-border rounded-lg bg-card overflow-hidden">
          <table className="w-full text-sm text-left">
            <thead className="bg-secondary/50 text-xs uppercase text-muted-foreground select-none">
              <tr>
                <th className="px-4 py-3 cursor-pointer hover:bg-secondary/80 transition-colors" onClick={() => requestSort("name")}><div className="flex items-center gap-1">Name <ArrowUpDown className="h-3 w-3" /></div></th>
                <th className="px-4 py-3 cursor-pointer hover:bg-secondary/80 transition-colors" onClick={() => requestSort("sizeBytes")}><div className="flex items-center gap-1">Size <ArrowUpDown className="h-3 w-3" /></div></th>
                <th className="px-4 py-3">Version</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredAndSortedResources.map((r) => {
                const isDeleting = deletingId === r.id;
                return (
                  <tr key={r.id} className="border-b border-border hover:bg-secondary/20 transition-colors">
                    <td className="px-4 py-3 font-medium"><div className="flex items-center gap-2">{getFileIcon(r.mimeType)}{r.name}</div></td>
                    <td className="px-4 py-3 text-muted-foreground">{(Number(r.sizeBytes) / 1024).toFixed(1)} KB</td>
                    <td className="px-4 py-3">
                      <button onClick={() => handleShowVersions(r)} className="inline-flex items-center gap-1 px-2 py-1 bg-secondary hover:bg-secondary/80 rounded text-xs font-medium transition-colors">
                        <History className="h-3 w-3" /> v{r.version}
                      </button>
                    </td>
                    <td className="px-4 py-3 text-right space-x-2">
                      <Button variant="outline" size="sm" onClick={() => { setShareResource(r); setShareUrl(null); }}>Share</Button>
                      {(r.mimeType.startsWith("image/") || r.mimeType.includes("pdf")) && <Button variant="outline" size="sm" onClick={() => handlePreview(r.filePath, r.mimeType)}>Preview</Button>}
                      <Button variant="outline" size="sm" onClick={() => handleDownload(r.filePath)}>Download</Button>
                      <Button variant="danger" size="sm" onClick={() => handleDelete(r.id)} disabled={isDeleting}>
                        {isDeleting ? <Loader2 className="h-3 w-3 animate-spin" /> : "Delete"}
                      </Button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Modals */}
      {previewUrl && (<div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4" onClick={() => setPreviewUrl(null)}><div className="bg-card p-4 rounded-lg max-w-4xl w-full max-h-screen overflow-auto" onClick={e => e.stopPropagation()}><div className="flex justify-between mb-4"><h3 className="font-bold">Preview</h3><Button variant="ghost" onClick={() => setPreviewUrl(null)}>Close</Button></div>{previewType?.includes("pdf") ? <iframe src={previewUrl} className="w-full h-[70vh] border-0" /> : <img src={previewUrl} alt="Preview" className="max-w-full mx-auto" />}</div></div>)}

      {shareResource && (<div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4"><div className="bg-card p-6 rounded-lg max-w-lg w-full space-y-4"><h3 className="font-bold text-lg">Share "{shareResource.name}"</h3>{!shareUrl ? (<><p className="text-sm text-muted-foreground">Valid for:</p><div className="grid grid-cols-2 sm:grid-cols-3 gap-2">{[1, 24, 168, 720, 8760].map(h => <Button key={h} type="button" variant="outline" onClick={() => handleCreateShare(shareResource, h)}>{h === 1 ? "1 Hour" : h === 24 ? "24 Hours" : h === 168 ? "7 Days" : h === 720 ? "1 Month" : "1 Year"}</Button>)}</div></>) : (<><p className="text-sm text-green-500">✅ Link ready!</p><div className="flex gap-2"><input type="text" readOnly value={shareUrl} className="flex-1 p-2 text-xs border border-border rounded bg-background" /><Button type="button" onClick={() => { navigator.clipboard.writeText(shareUrl); toast.success("Copied!"); }}>Copy</Button></div></>)}<div className="flex justify-end mt-4"><Button type="button" variant="ghost" onClick={() => { setShareResource(null); setShareUrl(null); }}>Close</Button></div></div></div>)}

      {versionsResource && (<div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4"><div className="bg-card p-6 rounded-lg max-w-lg w-full space-y-4"><h3 className="font-bold text-lg">Versions: "{versionsResource.name}"</h3><div className="max-h-64 overflow-y-auto space-y-2 pr-2">{versionsList.map(v => (<div key={v.id} className="flex items-center justify-between p-3 border border-border rounded-md bg-background"><div className="flex flex-col"><span className="font-bold text-sm">v{v.version} {v.isLatest && <span className="text-xs font-normal text-green-500 ml-1">(Latest)</span>}</span><span className="text-xs text-muted-foreground">{new Date(v.createdAt).toLocaleString()}</span></div><Button variant="outline" size="sm" onClick={() => handleDownload(v.filePath)}>Download</Button></div>))}</div><div className="flex justify-end mt-4"><Button type="button" variant="ghost" onClick={() => setVersionsResource(null)}>Close</Button></div></div></div>)}
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import { Folder, Trash2, Search, FileText } from "lucide-react";
import { toast } from "sonner";

export default function ProjectsPage() {
  const [projects, setProjects] = useState<any[]>([]);
  const [departments, setDepartments] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [newProjectName, setNewProjectName] = useState("");
  const [selectedDept, setSelectedDept] = useState("");
  const [loading, setLoading] = useState(true);
  const [role, setRole] = useState("");

  const fetchData = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const h = { Authorization: `Bearer ${session.access_token}` };

    const [pRes, dRes, meRes] = await Promise.all([
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/projects`, { headers: h }),
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/departments`, { headers: h }),
      fetch(`${process.env.NEXT_PUBLIC_API_URL}/users/me`, { headers: h })
    ]);

    if (meRes.ok) { const me = await meRes.json(); setRole(me.role); }
    if (pRes.ok) setProjects(await pRes.json());
    if (dRes.ok) {
      const deps = await dRes.json();
      setDepartments(deps);
      if (deps.length > 0) setSelectedDept(deps[0].id);
    }
    setLoading(false);
  };

  useEffect(() => { fetchData(); }, []);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProjectName || !selectedDept) return;
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/projects`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
      body: JSON.stringify({ name: newProjectName, departmentId: selectedDept })
    });
    if (res.ok) { toast.success("Project created"); setNewProjectName(""); fetchData(); }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure?")) return;
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/projects/${id}`, { method: "DELETE", headers: { Authorization: `Bearer ${session.access_token}` } });
    if (res.ok) { toast.success("Project deleted"); fetchData(); }
  };

  const filteredProjects = projects.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));
  if (loading) return <div className="p-8 animate-pulse text-muted-foreground">Loading projects...</div>;

  const isAdmin = role === "INSTITUTION_ADMIN" || role === "SUPER_ADMIN";

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end">
        <h1 className="text-3xl font-display font-bold">Projects</h1>
        <div className="relative w-64">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <input type="text" placeholder="Search projects..." value={search} onChange={(e) => setSearch(e.target.value)} className="w-full pl-9 pr-3 py-2 border border-border rounded-md bg-background text-sm" />
        </div>
      </div>

      {isAdmin && (
        <form onSubmit={handleCreate} className="flex gap-4 p-4 border border-border rounded-lg bg-card">
          <input placeholder="New project name" value={newProjectName} onChange={(e) => setNewProjectName(e.target.value)} className="flex-1 px-3 py-2 border border-border rounded-md bg-background text-sm" />
          <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-48 px-3 py-2 border border-border rounded-md bg-background text-sm">
            {departments.length === 0 && <option value="">Create a department first</option>}
            {departments.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
          <Button type="submit" disabled={departments.length === 0}>Create</Button>
        </form>
      )}

      {filteredProjects.length === 0 ? (
        <div className="text-center py-20 border border-border rounded-lg border-dashed bg-card">
          <Folder className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
          <h3 className="text-lg font-semibold">No projects found</h3>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredProjects.map((p) => (
            <div key={p.id} className="relative group p-6 border border-border rounded-lg bg-card hover:border-primary/50 transition-all">
              <Link href={`/dashboard/projects/${p.id}`} className="block">
                <Folder className="h-8 w-8 text-primary mb-4" />
                <h3 className="font-semibold text-lg">{p.name}</h3>
                <div className="flex items-center gap-4 mt-4 text-xs text-muted-foreground">
                  <span className="flex items-center gap-1"><FileText className="h-3 w-3" /> {p._count?.resources || 0} files</span>
                </div>
              </Link>
              {isAdmin && (
                <button onClick={(e) => { e.preventDefault(); handleDelete(p.id); }} className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 p-2 text-muted-foreground hover:text-red-500 rounded-md hover:bg-red-500/10">
                  <Trash2 className="h-4 w-4" />
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import { Trash2, RotateCcw, FileText } from "lucide-react";
import { toast } from "sonner";

export default function TrashPage() {
  const [resources, setResources] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchTrash = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/resources/trash`, {
      headers: { Authorization: `Bearer ${session.access_token}` },
    });
    if (res.ok) setResources(await res.json());
    setLoading(false);
  };

  useEffect(() => { fetchTrash(); }, []);

  const handleRestore = async (id: string) => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return;
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/resources/${id}/restore`, {
      method: "PATCH",
      headers: { Authorization: `Bearer ${session.access_token}` },
    });
    if (res.ok) {
      toast.success("File restored");
      fetchTrash();
    } else {
      toast.error("Failed to restore file");
    }
  };

  if (loading) return <div className="p-8 text-muted-foreground animate-pulse">Loading trash...</div>;

  return (
    <div className="space-y-6 max-w-5xl">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-3xl font-display font-bold">Trash</h1>
          <p className="text-muted-foreground mt-1">Deleted files are preserved for audit purposes.</p>
        </div>
      </div>

      {resources.length === 0 ? (
        <div className="text-center py-20 border border-border rounded-lg border-dashed bg-card">
          <Trash2 className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
          <h3 className="text-lg font-semibold">Trash is empty</h3>
        </div>
      ) : (
        <div className="border border-border rounded-lg bg-card overflow-hidden">
          <table className="w-full text-sm text-left">
            <thead className="bg-secondary/50 text-xs uppercase text-muted-foreground">
              <tr>
                <th className="px-4 py-3">Name</th>
                <th className="px-4 py-3">Size</th>
                <th className="px-4 py-3">Deleted At</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {resources.map((r) => (
                <tr key={r.id} className="border-b border-border">
                  <td className="px-4 py-3 font-medium">{r.name}</td>
                  <td className="px-4 py-3 text-muted-foreground">{(Number(r.sizeBytes) / 1024).toFixed(1)} KB</td>
                  <td className="px-4 py-3 text-muted-foreground">{new Date(r.deletedAt).toLocaleDateString()}</td>
                  <td className="px-4 py-3 text-right">
                    <Button variant="outline" size="sm" onClick={() => handleRestore(r.id)}>
                      <RotateCcw className="h-3 w-3 mr-1" /> Restore
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

"use client";

